preset.warp:
uniform sampler2D sampler_cover;
uniform sampler2D sampler_accent;
vec3 accent() {
  return texture(sampler_accent, vec2(0.5)).rgb;
}
// The cover's average colour at full brightness, for the gas giants'
// clouds; a grey cover gives way to warm sand, as a gas giant's own.
vec3 coverTone() {
  vec3 c = textureLod(sampler_cover, vec2(0.5), 10.0).rgb;
  float top = max(max(c.r, c.g), c.b);
  float saturation = top - min(min(c.r, c.g), c.b);
  vec3 tone = top > 0.01 ? c / top * 0.85 : vec3(0.0);
  return mix(vec3(0.85, 0.72, 0.55), tone, smoothstep(0.05, 0.25, saturation));
}
float hash13(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}
vec3 hash33(vec3 p) {
  p = fract(p * vec3(0.1031, 0.1030, 0.0973));
  p += dot(p, p.yxz + 33.33);
  return fract((p.xxy + p.yxx) * p.zyx);
}
float noise3(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), f.x),
        mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), f.x), f.y),
    mix(mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), f.x),
        mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), f.x), f.y),
    f.z);
}
float fbm(vec3 p, int octaves) {
  float sum = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 6; i++) {
    if (i >= octaves) break;
    sum += amp * noise3(p);
    p = p * 2.03 + 17.1;
    amp *= 0.5;
  }
  return sum;
}
// A star's colour at `kelvin`, brightest channel 1.
vec3 blackbody(float kelvin) {
  float t = kelvin / 100.0;
  float r = t <= 66.0 ? 1.0 : clamp(1.292936 * pow(t - 60.0, -0.1332047592), 0.0, 1.0);
  float g = t <= 66.0
    ? clamp(0.39008157 * log(t) - 0.63184144, 0.0, 1.0)
    : clamp(1.129890861 * pow(t - 60.0, -0.0755148492), 0.0, 1.0);
  float b = t >= 66.0 ? 1.0 : (t <= 19.0 ? 0.0 : clamp(0.54320679 * log(t - 10.0) - 1.19625409, 0.0, 1.0));
  vec3 c = vec3(r, g, b);
  c /= max(max(c.r, c.g), c.b);
  // A touch more colour than the physics: a sun-like star is white to the
  // eye, but should read as yellow on a screen beside a blue one.
  float grey = dot(c, vec3(0.3, 0.5, 0.2));
  return clamp(mix(vec3(grey), c, 1.5), 0.0, 1.0);
}
// The galaxy's disc, seen from inside it: a band across the sky, brighter
// and warmer towards the centre, cut by dust, with nebulae in the accent.
vec3 milkyWay(vec3 d) {
  vec3 n = normalize(vec3(0.25, 1.0, -0.25));
  vec3 c = normalize(vec3(0.9, 0.0, 0.5));
  c = normalize(c - n * dot(c, n));
  float lat = dot(d, n);
  float lon = atan(dot(d, cross(n, c)), dot(d, c));
  float centre = exp(-lon * lon * 1.1);
  float width = 0.09 + 0.12 * centre;
  float band = exp(-lat * lat / (width * width));
  float bulge = exp(-lat * lat / (0.01 + 0.03 * centre)) * centre;
  float clouds = fbm(d * 3.0, 5);
  float clumps = smoothstep(0.45, 0.8, fbm(d * 9.0 + 2.0, 5));
  float dust = smoothstep(0.4, 0.68, fbm(d * 7.0 + 7.0, 6)) * exp(-lat * lat / (0.003 + 0.004 * centre));
  vec3 col = mix(vec3(0.45, 0.52, 0.75), vec3(1.0, 0.82, 0.6), centre) * band * (0.1 + 0.6 * clouds + 0.6 * clumps) * 0.3;
  col += vec3(1.0, 0.8, 0.55) * bulge * 0.45;
  col *= 1.0 - 0.85 * dust;
  float nebula = smoothstep(0.55, 0.85, fbm(d * 5.0 + 13.0, 6)) * band;
  float filaments = smoothstep(0.35, 0.65, fbm(d * 14.0 + 3.0, 4));
  col += accent() * nebula * (0.08 + 0.3 * filaments);
  return col;
}
// Stars too far to move: three layers of cells on the sky, more of them
// in the band. `pix` is a pixel's angle; every star is at least that wide,
// so none flickers in and out between pixels.
vec3 farStars(vec3 d, float pix) {
  vec3 n = normalize(vec3(0.25, 1.0, -0.25));
  float lat = dot(d, n);
  float inBand = exp(-lat * lat / 0.02);
  vec3 col = vec3(0.0);
  for (int l = 0; l < 3; l++) {
    float scale = 60.0 * pow(2.3, float(l));
    vec3 cell = floor(d * scale);
    vec3 h = hash33(cell + float(l) * 31.7);
    if (h.x > 0.1 + 0.3 * inBand) continue;
    vec3 at = normalize(cell + 0.15 + 0.7 * hash33(cell + 5.1 + float(l)));
    float a = length(cross(d, at));
    float size = pix * 0.9;
    float lum = pow(h.y, 6.0) * 2.5 + 0.06;
    float twinkle = 1.0 + 0.35 * min(q22, 1.5) * sin(q17 * 40.0 + h.z * 60.0);
    col += blackbody(3000.0 + 11000.0 * h.z * h.z) * lum * twinkle * exp(-a * a / (size * size)) / (1.0 + float(l));
  }
  return col;
}
// The point of the segment a..b nearest the ray, its distance from the
// ray, and how far along the ray (t).
float rayToSegment(vec3 rd, vec3 a, vec3 b, out float t) {
  vec3 ba = b - a;
  vec3 oa = -a;
  float baba = dot(ba, ba);
  float rdba = dot(rd, ba);
  float denom = baba - rdba * rdba;
  float u = denom > 1e-6 ? clamp((dot(oa, ba) - rdba * dot(oa, rd)) / denom, 0.0, 1.0) : 0.0;
  vec3 p = a + ba * u;
  t = dot(p, rd);
  return length(p - rd * t);
}
// Stars close enough to fly past: one per cell of a grid in space, found
// by walking the cells along the ray. Each is drawn as the line it moves
// along during a frame or so, so at speed it streaks.
vec3 nearStars(vec3 rd, float pix) {
  const float GRID = 8.0;
  vec3 ro = vec3(0.0, 0.0, q18);
  vec3 p = ro / GRID;
  vec3 cell = floor(p);
  vec3 dirs = sign(rd);
  vec3 safe = vec3(abs(rd.x) < 1e-5 ? 1e-5 : rd.x, abs(rd.y) < 1e-5 ? 1e-5 : rd.y, abs(rd.z) < 1e-5 ? 1e-5 : rd.z);
  vec3 tDelta = abs(1.0 / safe);
  vec3 tMax = (cell + max(dirs, 0.0) - p) / safe;
  vec3 sweep = vec3(0.0, 0.0, -q19 * 5.0 - q24 * q24 * 30.0);
  vec3 col = vec3(0.0);
  for (int i = 0; i < 20; i++) {
    // The grid repeats every 1024 cells along the way, as the odometer
    // q18 does, so its wrapping moves nothing.
    vec3 key = vec3(cell.xy, mod(cell.z, 1024.0));
    vec3 h = hash33(key + 0.5);
    if (h.x < 0.3) {
      vec3 at = (cell + 0.2 + 0.6 * hash33(key + 7.3)) * GRID - ro;
      float t;
      float dist = rayToSegment(rd, at, at + sweep, t);
      if (t > 0.5) {
        float a = dist / t;
        float size = pix * 1.1;
        float streak = length(cross(rd, sweep)) / (t * pix);
        float lum = (0.3 + 2.5 * h.y * h.y * h.y) * 60.0 / (t * t + 40.0) * (1.0 + 3.0 * q24);
        col += blackbody(3000.0 + 12000.0 * h.z * h.z) * lum * exp(-a * a / (size * size)) / (1.0 + 0.5 * streak * (1.0 - 0.8 * q24));
      }
    }
    if (tMax.x < tMax.y) {
      if (tMax.x < tMax.z) { cell.x += dirs.x; tMax.x += tDelta.x; }
      else { cell.z += dirs.z; tMax.z += tDelta.z; }
    } else {
      if (tMax.y < tMax.z) { cell.y += dirs.y; tMax.y += tDelta.y; }
      else { cell.z += dirs.z; tMax.z += tDelta.z; }
    }
  }
  return col;
}
float ringDensity(float r, float fw) {
  if (r < 1.35 || r > 2.45) return 0.0;
  float x = (r - 1.35) / 1.1;
  // Fine ringlets fade out where a pixel spans several of them.
  float fine = mix(0.5, noise3(vec3(r * 40.0, q9, 0.0)), smoothstep(0.08, 0.02, fw * 40.0));
  float d = (0.55 + 0.45 * fine) * (0.55 + 0.45 * noise3(vec3(r * 9.0, q9 + 3.0, 0.0)));
  d *= smoothstep(0.0, 0.04, x) * smoothstep(1.0, 0.92, x);
  d *= 1.0 - 0.92 * exp(-pow((x - 0.62) / 0.025, 2.0));
  return d;
}
// A black hole (q8 2) at q4..q6, its disc's edge q7 out: the ray bent
// around it step by step (photons around a mass, in units of the horizon),
// where it leaves to (`dir`), and the disc it crossed on the way - in front
// and, bent over the top and under, behind.
void blackHole(vec3 rd, out vec3 dir, out vec3 col, out float alpha) {
  vec3 c = vec3(q4, q5, q6);
  float rs = q7 / 12.0;
  dir = rd;
  col = vec3(0.0);
  alpha = 0.0;
  vec3 p = -c / rs;
  vec3 v = rd;
  float along = dot(-p, v);
  float b = length(p + v * along);
  float r0 = length(p);
  if (b > 22.0 || (along < 0.0 && r0 > 30.0)) {
    // Far from it the light only leans in, by 2/b.
    vec3 toward = normalize(-p - v * along);
    float k = 2.0 / b * (0.5 + 0.5 * clamp(along / r0, -1.0, 1.0));
    dir = normalize(v + toward * k);
    return;
  }
  if (r0 > 30.0) p += v * (along - sqrt(max(900.0 - b * b, 0.0)));
  vec3 axis = normalize(vec3(sin(q15), cos(q15) * cos(q16), cos(q15) * sin(q16)));
  vec3 e1 = normalize(cross(axis, vec3(0.31, 0.17, 1.0)));
  vec3 e2 = cross(axis, e1);
  float h2 = b * b;
  for (int i = 0; i < 160; i++) {
    float r = length(p);
    if (r < 1.0) {
      alpha = 1.0;
      return;
    }
    if (r > 32.0 && dot(p, v) > 0.0) break;
    float dt = clamp(0.12 * (r - 0.9), 0.03, 1.5);
    v += -1.5 * h2 * p / pow(r, 5.0) * dt;
    vec3 pn = p + v * dt;
    float s0 = dot(p, axis);
    float s1 = dot(pn, axis);
    if (s0 * s1 < 0.0) {
      vec3 hit = mix(p, pn, s0 / (s0 - s1));
      float rr = length(hit);
      if (rr > 2.6 && rr < 12.0) {
        float x = (rr - 2.6) / 9.4;
        // Inner rings go round faster (Kepler), all of it with the music.
        float phi = atan(dot(hit, e2), dot(hit, e1)) + q17 * 6.0 / pow(rr, 1.5);
        float streaks = fbm(vec3(rr * 3.0, cos(phi) * 1.6, sin(phi) * 1.6), 4);
        float light = pow(1.0 - x, 1.6) * smoothstep(0.0, 0.04, x) * smoothstep(1.0, 0.75, x);
        // The side coming towards the camera is brighter.
        vec3 vel = normalize(cross(axis, hit)) * sqrt(0.5 / rr);
        float doppler = 1.0 / (1.0 - dot(vel, -normalize(v)));
        // Hot gas glows warm: white-gold inside, deep orange at the edge.
        vec3 hot = blackbody(mix(6500.0, 2400.0, pow(x, 0.5))) * vec3(1.0, 0.8, 0.55);
        vec3 disc = hot * light * (0.4 + 2.2 * streaks * streaks);
        disc *= min(doppler * doppler, 3.0) * 1.4 * (1.0 + 0.5 * q21);
        float cover = clamp(light * 1.6, 0.0, 0.95);
        col += (1.0 - alpha) * disc;
        alpha += (1.0 - alpha) * cover;
      }
    }
    p = pn;
  }
  dir = normalize(v);
}
float sphereHit(vec3 ro, vec3 rd, vec3 c, float r) {
  vec3 oc = ro - c;
  float b = dot(oc, rd);
  float h = b * b - dot(oc, oc) + r * r;
  if (h < 0.0) return -1.0;
  return -b - sqrt(h);
}
// A star at c, radius R, `kelvin` hot: its surface (colour, how much of
// what is behind it it covers), its corona as `glow`, and how far along
// the ray it is.
vec4 starBody(vec3 rd, vec3 c, float R, float kelvin, float seed, float pix, out vec3 glow, out float depth) {
  vec3 bb = blackbody(kelvin);
  // Corona by angle from the star's centre, so it carries on smoothly
  // past the edge of the view as the star goes by.
  float cl = length(c);
  float apparent = asin(min(R / cl, 1.0));
  float x = max(acos(clamp(dot(rd, c / cl), -1.0, 1.0)) - apparent, 0.0) / apparent;
  vec3 off = normalize(rd - c / cl * dot(rd, c / cl) + 1e-6);
  float streamers = fbm(off * 3.0 + vec3(seed, 0.0, q17 * 0.6), 3);
  // A haze of the star's light around it, filling the view when near.
  float corona = exp(-x * 9.0) * 1.4 + exp(-x * 2.2) * 0.5 * (0.4 + streamers) + exp(-x * 0.5) * 0.14;
  glow = bb * corona * (1.0 + 0.7 * q21);
  depth = cl;
  float tc = dot(c, rd);
  if (tc <= 0.0) return vec4(0.0);
  float dc = length(c - rd * tc);
  float cover = clamp((R - dc) / (pix * tc) + 0.5, 0.0, 1.0);
  if (cover <= 0.0) return vec4(0.0);
  float tHit = tc - sqrt(max(R * R - dc * dc, 0.0));
  depth = tHit;
  vec3 n = normalize(rd * tHit - c);
  float mu = max(dot(n, -rd), 0.0);
  // Plasma: noise pushed around by noise, so it folds into swirls, and
  // all of it flowing with the music. A bright glowing ground with
  // crumbly white-hot patches in it, a few fine filaments between.
  float t = q17 * 0.25;
  vec3 p = n * 4.0 + seed;
  vec3 flow = vec3(fbm(p + vec3(0.0, 0.0, t), 4),
                   fbm(p + vec3(5.2, 1.3, t), 4),
                   fbm(p + vec3(2.1, 7.7, -t), 4));
  float plasma = fbm(p * 2.0 + 3.0 * flow + vec3(t * 0.7), 5);
  float threads = 1.0 - abs(2.0 * fbm(n * 9.0 + 2.5 * flow + t * 0.9, 4) - 1.0);
  float grain = fbm(n * 32.0 + 4.0 * flow + t * 1.5, 3);
  float heat = clamp(plasma * 1.3 - 0.2 + pow(threads, 8.0) * 0.35 + (grain - 0.5) * 1.1, 0.0, 1.4);
  // The ramp from the star's own colour: deeper below it, white-hot
  // above, so a blue star burns blue and a red one red. Squaring the
  // colour deepens it without turning it brown.
  vec3 cool = pow(blackbody(kelvin * 0.55), vec3(2.2));
  vec3 surface = mix(cool * 0.75, cool * 1.25, smoothstep(0.1, 0.6, heat));
  surface = mix(surface, bb * 1.4, smoothstep(0.6, 0.95, heat));
  surface = mix(surface, mix(bb, vec3(1.0, 0.96, 0.85), 0.6) * 2.6, smoothstep(0.95, 1.25, heat));
  // Darker and redder towards the rim, as a real star's edge.
  float limb = 0.55 + 0.45 * pow(mu, 0.5);
  surface *= limb * mix(vec3(1.0, 0.6, 0.35), vec3(1.0), pow(mu, 0.35));
  // The rim glows into the corona rather than ending in an edge.
  surface += bb * pow(1.0 - mu, 4.0) * 0.8;
  return vec4(surface * cover, cover);
}
// A gas giant at c, radius R, lit from direction L by `sun`.
vec4 giantBody(vec3 rd, vec3 c, float R, vec3 L, vec3 sun, float pix, out float depth) {
  depth = length(c);
  float tc = dot(c, rd);
  if (tc <= 0.0) return vec4(0.0);
  float dc = length(c - rd * tc);
  float cover = clamp((R - dc) / (pix * tc) + 0.5, 0.0, 1.0);
  float tHit = tc - sqrt(max(R * R - dc * dc, 0.0));
  if (cover > 0.0) depth = tHit;
  vec3 n = normalize(rd * tHit - c);
  float mu = max(dot(n, -rd), 0.0);
  vec3 axis = normalize(vec3(sin(q15), cos(q15) * cos(q16), cos(q15) * sin(q16)));
  vec3 planet = vec3(0.0);
  if (cover > 0.0) {
    vec3 e1 = normalize(cross(axis, vec3(0.31, 0.17, 1.0)));
    vec3 e2 = cross(axis, e1);
    float lat = dot(n, axis);
    // Each latitude turns at its own speed, as a gas giant's bands do,
    // and with the music.
    float spin = q17 * 0.06 * (1.0 + 0.6 * sin(lat * 23.0 + q9));
    vec2 around = vec2(dot(n, e1), dot(n, e2));
    around = vec2(cos(spin) * around.x - sin(spin) * around.y, sin(spin) * around.x + cos(spin) * around.y);
    vec3 turned = axis * lat + e1 * around.x + e2 * around.y;
    // Noise stretched along the bands - slow around, fast across - so
    // it draws streaks, and pushed by itself where bands shear past.
    float turb = fbm(vec3(around * 1.6, lat * 10.0) + q9, 5);
    float shear = fbm(vec3(around * 3.0, lat * 45.0) + turb * 2.0 + q9, 4);
    float bent = lat + (turb - 0.5) * 0.08 + (shear - 0.5) * 0.035;
    float pattern = 0.5 + 0.3 * sin(bent * 24.0 + q9) + 0.2 * sin(bent * 63.0 + q9 * 1.7);
    pattern += (shear - 0.5) * 0.35;
    float streaks = fbm(vec3(around * 4.0, lat * 220.0) + shear * 2.0 + q9, 4);
    pattern += (streaks - 0.5) * 0.5;
    // The cover's colour, deep in the dark bands and pale in the light.
    vec3 tone = coverTone();
    vec3 dark = tone * 0.3 + vec3(0.01, 0.01, 0.02);
    vec3 mid = tone * 0.7;
    vec3 pale = mix(tone, vec3(0.93, 0.93, 0.97), 0.75);
    vec3 albedo = mix(dark, mid, smoothstep(0.2, 0.5, pattern));
    albedo = mix(albedo, pale, smoothstep(0.62, 0.9, pattern));
    // Storms: small ovals drifting with their band, a pale one with a
    // turbulent inside, now and then a dark one in a pale rim.
    vec3 cell = floor(turned * 4.0);
    vec3 h = hash33(cell + q9);
    if (h.x < 0.25) {
      vec3 centre = normalize(cell + 0.35 + 0.3 * hash33(cell + q9 + 3.1));
      vec3 d = turned - centre;
      float across = dot(d, axis);
      float along = dot(d, normalize(cross(axis, centre)));
      float size = 0.015 + 0.03 * h.y;
      float v = length(vec2(along / 1.6, across)) / size;
      float body = smoothstep(1.0, 0.55, v) * 0.85;
      float rim = smoothstep(0.55, 0.9, v) * smoothstep(1.3, 0.95, v);
      float inside = fbm(vec3(along, across, 0.0) / size * 1.5 + q9 + h.y * 10.0, 3);
      if (h.z < 0.85) {
        vec3 storm = mix(pale, mid, smoothstep(0.35, 0.0, v) * 0.5) * (0.85 + 0.3 * inside);
        albedo = mix(albedo, storm, body * 0.9);
      } else {
        albedo = mix(albedo, dark * 0.6 * (0.8 + 0.4 * inside), body);
        albedo = mix(albedo, pale, rim * 0.4);
      }
    }
    // Soft light that wraps a little past the terminator, as through a
    // deep atmosphere.
    float facing = dot(n, L);
    float lit = max(facing * 0.85 + 0.15, 0.0) / 1.0;
    float terminator = smoothstep(-0.15, 0.25, facing);
    vec3 p = rd * tHit;
    float shadow = 0.0;
    if (q14 > 0.5) {
      float tr = dot(c - p, axis) / dot(L, axis);
      if (tr > 0.0) shadow = ringDensity(length(p + L * tr - c) / R, 0.0);
    }
    planet = albedo * sun * (0.06 + 1.15 * lit) * terminator * (1.0 - 0.8 * shadow);
    // Its atmosphere catching the light at the rim - all round when the
    // sun is behind it.
    float backlight = 0.35 + 1.2 * max(dot(-rd, -L), 0.0);
    planet += mix(sun, tone, 0.5) * pow(1.0 - mu, 3.0) * 0.4 * backlight * smoothstep(-0.4, 0.2, facing);
  }
  vec4 col = vec4(planet * cover, cover);
  if (q14 > 0.5) {
    float tp = dot(c, axis) / dot(rd, axis);
    if (tp > 0.0) {
      vec3 at = rd * tp;
      float r = length(at - c) / R;
      float fw = pix * tp / R / max(abs(dot(rd, axis)), 0.05);
      float density = ringDensity(r, fw) * 0.9;
      if (density > 0.0) {
        float shade = sphereHit(at, L, c, R) > 0.0 ? 0.12 : 1.0;
        vec3 ring = mix(coverTone(), vec3(0.9, 0.85, 0.78), 0.6) * sun * shade * (0.35 + 0.65 * abs(dot(L, axis)));
        bool inFront = cover <= 0.0 || tp < tHit;
        if (inFront) {
          col = vec4(mix(col.rgb, ring, density), 1.0 - (1.0 - col.a) * (1.0 - density));
          depth = min(depth, tp);
        } else col = vec4(col.rgb + ring * density * (1.0 - col.a), col.a + density * (1.0 - col.a));
      }
    }
  }
  return col;
}
// `v` turned by `angle` around `axis`.
vec3 turn(vec3 v, vec3 axis, float angle) {
  return v * cos(angle) + cross(axis, v) * sin(angle) + axis * dot(axis, v) * (1.0 - cos(angle));
}
// Land: broad continents with ridged mountain chains in them, 0..1.
float terrain(vec3 p) {
  float broad = fbm(p * 1.6, 5);
  float ridges = 1.0 - abs(2.0 * fbm(p * 4.0 + 7.0, 4) - 1.0);
  return broad + 0.22 * ridges * ridges * smoothstep(0.45, 0.65, broad);
}
// Clouds: noise pushed around by noise into swirls and fronts, drifting
// with the music. `cover` from 0 (clear) to 1 (overcast).
// Pushed twice, the second push by the first, which curls it; stretched
// along the latitudes, as winds draw clouds out.
float clouds(vec3 p, vec3 axis, float cover) {
  p += axis * dot(p, axis) * 0.8;
  vec3 a = vec3(fbm(p * 1.8, 4), fbm(p * 1.8 + 5.2, 4), fbm(p * 1.8 + 9.1, 4));
  vec3 b = vec3(fbm(p * 1.8 + a * 4.0 + 1.7, 4), fbm(p * 1.8 + a * 4.0 + 8.3, 4), fbm(p * 1.8 + a * 4.0 + 2.8, 4));
  float c = fbm(p * 3.0 + b * 3.0, 5);
  float wisps = fbm(p * 14.0 + b * 6.0, 3);
