  if (h.x > 0.55) return 0.0;
  vec3 centre = normalize(cell + 0.3 + 0.4 * hash33(cell + seed + 4.7));
  vec3 d = p - centre;
  float size = (0.18 + 0.25 * h.y) / scale;
  float v = length(d) / size;
  if (v > 1.4) return 0.0;
  // Bowl sloping down to the middle, a rim sloping up and away.
  float slope = v < 1.0 ? 1.6 * v : -3.0 * (1.4 - v);
  vec3 outward = normalize(d - p * dot(d, p) + 1e-6);
  float lightAcross = dot(outward, L);
  return -slope * lightAcross * 0.35 + (v < 1.0 ? -0.08 : 0.0);
}
