  col += vec3(1.0, 0.7, 0.35) * lights * (1.0 - cloud) * 0.6;
  if (air) {
    // Blue haze, thickest at the rim, on the day side.
    col += sky * sun * pow(1.0 - mu, 2.5) * 0.7 * smoothstep(-0.3, 0.3, facing);
  }
  return vec4(col * cover, cover);
}
// The system: a star (q8 0), a gas giant (q8 1) or a world (q8 3..5) at q4..q6 from the
