  vec4 b = starBody(rd, c2, q30, q31, q9 + 17.0, pix, g2, d2);
  vec4 near = a;
  vec4 far = b;
  vec3 gNear = g1;
  vec3 gFar = g2;
  if (d2 < d1) {
    near = b;
    far = a;
    gNear = g2;
    gFar = g1;
  }
  glow = gNear * (1.0 - 0.85 * near.a) + gFar * (1.0 - near.a) * (1.0 - 0.85 * far.a);
